(1368095, 174497, 34134, '<td valign="top">This is an exceptional photo. High quality, great lighting, and wonderful composition. The gold against the black is VERY effective. Extremely sharp. I can even see the ridges on the coin edges. Good job, and pleasant dreams.</td>', 'This is an exceptional photo. High quality, great lighting, and wonderful composition. The gold against the black is VERY effective. Extremely sharp. I can even see the ridges on the coin edges. Good job, and pleasant dreams.', '2005-05-06 19:57:12.000000', NULL, 1),
(1368096, 173506, 3032, '<td valign="top">A crossing between the moon, mr Sandman and wolf... It looks a bit to photoshopped for a photo, but nevertheless I like it a lot as a work of art.</td>', 'A crossing between the moon, mr Sandman and wolf... It looks a bit to photoshopped for a photo, but nevertheless I like it a lot as a work of art.', '2005-05-06 19:57:45.000000', NULL, 1),
