(1375496, 174535, 16488, '<td valign="top">Interesting abstract!  I love the way you''ve used a tunnel of reflective material to interpret the subject.  It''s too bad that some of those menacing spikes are not as sharply focused as they are sharp.  Worth a re-do, IMHO...</td>', 'Interesting abstract!  I love the way you''ve used a tunnel of reflective material to interpret the subject.  It''s too bad that some of those menacing spikes are not as sharply focused as they are sharp.  Worth a re-do, IMHO...', '2005-05-10 13:53:55.000000', NULL, 1),
(1375504, 174643, 16488, '<td valign="top">Wonderfully bizarre!  The colors are incredible!  Looking forward to your processing notes...</td>', 'Wonderfully bizarre!  The colors are incredible!  Looking forward to your processing notes...', '2005-05-10 13:56:53.000000', NULL, 1),
(1375509, 174446, 16488, '<td valign="top">Great concept!  Looks like you had fun creating it.  There is fringing or oversharpening that gives this the illusion of being cut and paste, unfortunately.</td>', 'Great concept!  Looks like you had fun creating it.  There is fringing or oversharpening that gives this the illusion of being cut and paste, unfortunately.', '2005-05-10 13:58:44.000000', NULL, 1),
(1375510, 173644, 16488, '<td valign="top">Wow!  What fun this image is!  The colors are pure joy!  Curious to learn about the object made from horseshoes--hope to see that in your notes after the challenge.  Top score!</td>', 'Wow!  What fun this image is!  The colors are pure joy!  Curious to learn about the object made from horseshoes--hope to see that in your notes after the challenge.  Top score!', '2005-05-10 14:00:41.000000', NULL, 1),
(1375532, 174313, 34252, '<td valign="top">This is a powerful image. Do you have a shot in this series that is not as centered and from a ground perspective?</td>', 'This is a powerful image. Do you have a shot in this series that is not as centered and from a ground perspective?', '2005-05-10 14:07:02.000000', NULL, 1),
