(1375990, 174643, 30214, '<td valign="top">great shot!</td>', 'great shot!', '2005-05-10 17:19:16.000000', NULL, 1),
(1375992, 173097, 30214, '<td valign="top">very eerie shot, I like it!</td>', 'very eerie shot, I like it!', '2005-05-10 17:20:20.000000', NULL, 1),
(1376129, 174530, 25022, '<td valign="top">Reminiscent of 18/19th century pastoral landscape paintings.  Check out //www.tate.org.uk/servlet/CollectionDisplays?roomid=1992 .  Its a very evocative scene.  I particularly like the shift from a dark foreground receding into a lit background with ones view partially obstructed by foliage thus creating a sense of unattainability.  The lit fields are on the other side of the river bank/lake and beyond my reach. Congratulations on a truly beautiful photo.  Wonder if you''d be willing to share the technique you used?  I''d love to try and replicate something like this.</td>', 'Reminiscent of 18/19th century pastoral landscape paintings.  Check out //www.tate.org.uk/servlet/CollectionDisplays?roomid=1992 .  Its a very evocative scene.  I particularly like the shift from a dark foreground receding into a lit background with ones view partially obstructed by foliage thus creating a sense of unattainability.  The lit fields are on the other side of the river bank/lake and beyond my reach. Congratulations on a truly beautiful photo.  Wonder if you''d be willing to share the technique you used?  I''d love to try and replicate something like this.', '2005-05-10 18:47:03.000000', NULL, 1),
(1376131, 174581, 25022, '<td valign="top">one ugly beast</td>', 'one ugly beast', '2005-05-10 18:50:03.000000', NULL, 1),
(1376584, 172472, 16488, '<td valign="top">Appropriately surreal!  Hard to find fault with this--even with the long title.  Somehow it just works.</td>', 'Appropriately surreal!  Hard to find fault with this--even with the long title.  Somehow it just works.', '2005-05-10 23:16:00.000000', NULL, 1),
(1376595, 174600, 14763, '<td valign="top">Beautiful!!! One of my favorites</td>', 'Beautiful!!! One of my favorites', '2005-05-10 23:26:17.000000', NULL, 1),
