(1376645, 174083, 16488, '<td valign="top">Wonderful use of sepia!  Love the way the horizon fades away!</td>', 'Wonderful use of sepia!  Love the way the horizon fades away!', '2005-05-11 00:00:01.000000', NULL, 1),
