(1382053, 173992, 23203, '<td valign="top">Neat idea - perfect lighting.. such a nice dreamy feeling<br/></td>', 'Neat idea - perfect lighting.. such a nice dreamy feeling', '2005-05-12 18:46:05.000000', NULL, 1),
(1382083, 173431, 4411, '<td valign="top">Superb contrast between the rocks and the water. The streaks of water spraying up are very cool too.</td>', 'Superb contrast between the rocks and the water. The streaks of water spraying up are very cool too.', '2005-05-12 18:57:13.000000', NULL, 1),
(1382096, 173176, 4411, '<td valign="top">The noise/grain in the background on this gives it a very strange real/digital split effect. Very cool.</td>', 'The noise/grain in the background on this gives it a very strange real/digital split effect. Very cool.', '2005-05-12 18:59:14.000000', NULL, 1),
(1382151, 174305, 4411, '<td valign="top">A very neat idea. If anything the change from blurry to sharp is too sudden. Maybe you could have panned the camera too? I dunno ''cos I don''t know exactly how you''ve done this!<br/>Love the colours and the blurry bit. Less keen on the center. Would love to see more experiments like this though.</td>', 'A very neat idea. If anything the change from blurry to sharp is too sudden. Maybe you could have panned the camera too? I dunno ''cos I don''t know exactly how you''ve done this!Love the colours and the blurry bit. Less keen on the center. Would love to see more experiments like this though.', '2005-05-12 19:21:35.000000', NULL, 1),
(1382162, 174643, 4411, '<td valign="top">I can''t figure this out, which makes it all the more intruiging.<br/>The fisheye effect works well and the overall colours are great. Can''t say much more!</td>', 'I can''t figure this out, which makes it all the more intruiging.The fisheye effect works well and the overall colours are great. Can''t say much more!', '2005-05-12 19:27:49.000000', NULL, 1),
(1382166, 174400, 4411, '<td valign="top">Difficult to look at this one because it seems to be moving all the time! A great scene, well composed with great colours, but the zoom effect will give me a headache if I don''t move on quickly!</td>', 'Difficult to look at this one because it seems to be moving all the time! A great scene, well composed with great colours, but the zoom effect will give me a headache if I don''t move on quickly!', '2005-05-12 19:29:38.000000', NULL, 1),
(1382177, 174074, 4411, '<td valign="top">Nice macro. Love the deep green background and the overall composition. Centered? Who cares, it works here.</td>', 'Nice macro. Love the deep green background and the overall composition. Centered? Who cares, it works here.', '2005-05-12 19:35:51.000000', NULL, 1),
(1382187, 174688, 23680, '<td valign="top">One of my favorites - oh the horror - it''s a flower :)   I love the colors and dreamy nature of this, great job - 10</td>', 'One of my favorites - oh the horror - it''s a flower :)   I love the colors and dreamy nature of this, great job - 10', '2005-05-12 19:49:10.000000', NULL, 1),
(1382188, 174691, 23680, '<td valign="top">One of my only 2 10''s of this challenge - great job, I like everything about this.</td>', 'One of my only 2 10''s of this challenge - great job, I like everything about this.', '2005-05-12 19:49:57.000000', NULL, 1),
