(1382233, 174400, 26679, '<td valign="top">wooh  I like the idea but this really hurts my eyes, which is a shame as the concept is great</td>', 'wooh  I like the idea but this really hurts my eyes, which is a shame as the concept is great', '2005-05-12 20:17:07.000000', NULL, 1),
(1382236, 172293, 26679, '<td valign="top">The lighting is dreamy and picturesque, well done</td>', 'The lighting is dreamy and picturesque, well done', '2005-05-12 20:18:39.000000', NULL, 1),
(1382239, 174216, 26679, '<td valign="top">The tree is a great capture, its a shame that the torch light is too blown out. I wouldhabe like to see a little local tonal adjustment here..</td>', 'The tree is a great capture, its a shame that the torch light is too blown out. I wouldhabe like to see a little local tonal adjustment here..', '2005-05-12 20:19:44.000000', NULL, 1),
