(1382873, 174530, 23203, '<td valign="top">Congratulations! I''d love to see a ''how they did it'' kind of tutorial on this.<br/></td>', 'Congratulations! I''d love to see a ''how they did it'' kind of tutorial on this.', '2005-05-13 01:17:19.000000', NULL, 0),
(1382874, 173059, 8891, '<td valign="top">Wonderful dreamlike effect you got with the fish-eye, Christina! Many congrats on your blue!</td>', 'Wonderful dreamlike effect you got with the fish-eye, Christina! Many congrats on your blue!', '2005-05-13 01:18:19.000000', NULL, 0),
