(1382879, 174301, 35169, '<td valign="top">congradulations on the ribbon.  I read its your 1st. Awesome, you''ve broke the mold now.  Terrific image too</td>', 'congradulations on the ribbon.  I read its your 1st. Awesome, you''ve broke the mold now.  Terrific image too', '2005-05-13 01:20:27.000000', NULL, 0),
(1382880, 173059, 20608, '<td valign="top">Oh how i miss my fisheye (sold due to camera upgrade) you certainly made it work for you in this image, a wonderful shot congrats on the BLUEY!!!</td>', 'Oh how i miss my fisheye (sold due to camera upgrade) you certainly made it work for you in this image, a wonderful shot congrats on the BLUEY!!!', '2005-05-13 01:21:17.000000', NULL, 0),
